import { readFile, writeFile } from 'node:fs/promises';

const file = new URL('../lib/spark-pb.js', import.meta.url);
let source = await readFile(file, 'utf8');

// pbjs emits an extensionless CommonJS import; Node ESM needs the file name.
source = source.replace(
  /import \* as \$protobuf from ["']protobufjs\/minimal["'];/u,
  'import $protobuf from "protobufjs/minimal.js";',
);

const header = `/*
 * Generated by protobufjs-cli from the official spark Protocol Buffer schemas.
 * Schema source: lucko/spark commit 3e8745a76eaabe9a4f70aad6283876fb518d2ae8.
 * This file is part of DSH Spark Insights and is licensed GPL-3.0-only.
 * See NOTICE for attribution.
 */
`;

if (!source.startsWith('/*\n * Generated by protobufjs-cli')) {
  source = header + source;
}

await writeFile(file, source);
